#[derive(Debug, Clone)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

impl Point {
    pub fn dist(&self, other: &Point) -> f64 {
        ((self.x - other.x).powi(2) + (self.y - other.y).powi(2)).sqrt()
    }
}

#[derive(Debug)]
enum Shape {
    Circle { r: f64 },
    Rect { w: f64, h: f64 },
}

fn area(s: &Shape) -> f64 {
    match s {
        Shape::Circle { r } => std::f64::consts::PI * r * r,
        Shape::Rect { w, h } => w * h,
    }
}

use std::fs;
use std::io;

fn load_lines(path: &str) -> io::Result<Vec<String>> {
    let raw = fs::read_to_string(path)?;
    let lines = raw
        .lines()
        .map(|l| l.trim().to_owned())
        .filter(|l| !l.is_empty())
        .collect();
    Ok(lines)
}

use std::collections::HashMap;

pub fn group_by<'a, T, K, F>(items: &'a [T], key: F) -> HashMap<K, Vec<&'a T>>
where
    K: std::hash::Hash + Eq,
    F: Fn(&T) -> K,
{
    let mut out: HashMap<K, Vec<&'a T>> = HashMap::new();
    for item in items {
        out.entry(key(item)).or_default().push(item);
    }
    out
}

use std::fmt;

#[derive(Debug)]
pub enum ConfigError {
    Missing(&'static str),
    Parse(std::num::ParseIntError),
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::Missing(k) => write!(f, "missing key: {k}"),
            ConfigError::Parse(e) => write!(f, "bad number: {e}"),
        }
    }
}

impl From<std::num::ParseIntError> for ConfigError {
    fn from(e: std::num::ParseIntError) -> Self {
        ConfigError::Parse(e)
    }
}

pub fn port_from_env() -> u16 {
    std::env::var("PORT")
        .ok()
        .and_then(|raw| raw.parse::<u16>().ok())
        .unwrap_or(8080)
}

pub trait Drill {
    fn name(&self) -> &str;

    fn label(&self) -> String {
        format!("drill: {}", self.name())
    }
}

pub fn depth(root: Node) -> usize {
    let mut stack = vec![(root, 1usize)];
    let mut best = 0;
    while let Some((node, d)) = stack.pop() {
        best = best.max(d);
        for child in node.children {
            stack.push((child, d + 1));
        }
    }
    best
}

use std::collections::HashMap;

pub fn tally(lines: &[String]) -> HashMap<String, usize> {
    let mut out = HashMap::new();
    for line in lines {
        for word in line.split_whitespace() {
            *out.entry(word.to_lowercase()).or_insert(0) += 1;
        }
    }
    out
}

pub fn weighted_score(hits: &[u32], weights: &[u32]) -> f64 {
    let total: u32 = hits
        .iter()
        .zip(weights.iter())
        .map(|(hit, weight)| hit * weight)
        .sum();
    let count: u32 = weights.iter().sum();
    f64::from(total) / f64::from(count.max(1))
}

use std::sync::{Arc, Mutex};
use std::thread;

pub fn parallel_tally(chunks: Vec<Vec<u32>>) -> u32 {
    let total = Arc::new(Mutex::new(0u32));
    let mut handles = Vec::new();

    for chunk in chunks {
        let total = Arc::clone(&total);
        handles.push(thread::spawn(move || {
            *total.lock().unwrap() += chunk.iter().sum::<u32>();
        }));
    }

    for handle in handles {
        handle.join().unwrap();
    }

    let sum = *total.lock().unwrap();
    sum
}

use std::collections::HashSet;
use std::hash::Hash;

pub fn dedup_by<T, K, F>(items: Vec<T>, key: F) -> impl Iterator<Item = T>
where
    K: Hash + Eq,
    F: Fn(&T) -> K,
{
    let mut seen = HashSet::new();
    items.into_iter().filter(move |item| seen.insert(key(item)))
}

use std::error::Error;
use std::fs;

pub fn load_port(path: &str) -> Result<u16, Box<dyn Error>> {
    let raw = fs::read_to_string(path)?;
    let line = raw
        .lines()
        .find(|l| l.starts_with("port="))
        .ok_or("missing port key")?;
    let port = line.trim_start_matches("port=").trim().parse::<u16>()?;
    Ok(port)
}

#[derive(Debug, PartialEq)]
pub enum Cmd<'a> {
    Help,
    Run { lang: &'a str, minutes: u32 },
    Unknown(&'a str),
}

pub fn parse(args: &[String]) -> Cmd<'_> {
    match args {
        [] | [_] => Cmd::Help,
        [_, cmd, lang, rest @ ..] if cmd == "run" => Cmd::Run {
            lang: lang.as_str(),
            minutes: rest.first().and_then(|m| m.parse().ok()).unwrap_or(10),
        },
        [_, other, ..] => Cmd::Unknown(other.as_str()),
    }
}
